  "stuSess.penaltyChoiceRefundDesc": "Щоб повернути €{amount}, зверніться на info@tutlio.lt. Якщо ви сплатили карткою, повернення також може розпочатися автоматично через Stripe.",
  "stuSess.creditAvailable": "Доступний залишок",
  "stuSess.payWithCredit": "Сплатити з балансу",
  "stuSess.creditAppliedSuccess": "€{amount} додано на ваш баланс. Ці кошти буде автоматично використано для оплати наступного заняття.",
  "stuSess.refundContactNote": "Щоб повернути кошти, зверніться на <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">Маєте запитання або проблему? Напишіть на <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">Повернення коштів через Stripe розпочато.</p><p class=\"text-emerald-800 mt-1\">Кошти зазвичай повертаються на картку протягом приблизно <strong>5–10 робочих днів</strong> (залежить від банку). Якщо кошти не надійшли у звичайний термін, напишіть на <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Схоже, це заняття оплачено не через Stripe у Tutlio, а, наприклад, банківським переказом або готівкою. Автоматичне повернення тут недоступне.</p><p class=\"mt-2\">Щоб узгодити повернення, зверніться до свого репетитора <strong>{tutor}</strong> за електронною поштою або контактами з бронювання чи від самого репетитора.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Схоже, це заняття оплачено не через Stripe у Tutlio, а, наприклад, банківським переказом або готівкою. Автоматичне повернення тут недоступне.</p><p class=\"mt-2\">Оскільки ви навчаєтеся через організацію, зверніться до <strong>адміністратора організації</strong> через репетитора або за опублікованими контактами організації.</p>",
  "stuSess.refundTutorFallback": "ваш репетитор",
