  "landing.faq.whatIsQ": "Що таке Tutlio?",
  "landing.faq.whatIsA": "Tutlio - платформа для індивідуальних репетиторів і репетиторських шкіл, що об’єднує керування розкладом, оплатами, спілкуванням з учнями й обліком занять.",
  "landing.faq.whoForQ": "Для кого Tutlio?",
  "landing.faq.whoForA": "Tutlio створено для індивідуальних репетиторів, викладачів музики й мов, репетиторів математики, репетиторських шкіл і навчальних центрів будь-якого розміру.",
  "landing.faq.waitlistQ": "Як працює список очікування учнів?",
  "landing.faq.waitlistA": "Коли учень скасовує заняття, вільний час автоматично пропонується учням зі списку очікування. Місце отримує той, хто підтвердить першим, - тому репетитори не втрачають дохід через скасування.",
  "landing.faq.freeTrialQ": "Чи є безкоштовний пробний період?",
  "landing.faq.freeTrialA": "Так! Кожен новий обліковий запис автоматично отримує 7 безкоштовних днів - код не потрібен. Протягом пробного періоду кошти не списуються, скасувати можна будь-коли.",
  "landing.faq.languagesQ": "Які мови підтримує Tutlio?",
  "landing.faq.languagesA": "Tutlio доступний {count} мовами: {languages}.",
  "landing.faqTitle": "Поширені запитання",
  "landing.feature.digital-business-card": "Цифрова візитка",
  "landing.feature.digital-business-cardDesc": "Поділіться професійно оформленою сторінкою, де учні можуть дізнатися про вас, побачити актуальні ціни й вільний час та одразу надіслати запит на заняття.",
  "featuresIndex.newBadge": "Нове",
  "feature.digital-business-card.pageTitle": "Цифрова візитка, що перетворює зацікавлення на запити про заняття",
  "feature.digital-business-card.pageDesc": "Дайте кожному потенційному учневі одне зручне посилання з інформацією про вас, заняття, ціни, відгуки й актуальний вільний час. Учні одразу вибирають заняття та час, а запити не губляться в довгому листуванні.",
  "feature.digital-business-card.detailsTitle": "Усе необхідне потенційному учневі для рішення",
  "feature.digital-business-card.oneLink": "Одне посилання для всього репетиторського бізнесу",
  "feature.digital-business-card.oneLinkDesc": "Замініть розрізнені профілі в соцмережах, прайси й повідомлення про бронювання однією сторінкою, якою можна ділитися будь-де.",
  "feature.digital-business-card.liveAvailability": "Завжди актуальний вільний час",
  "feature.digital-business-card.liveAvailabilityDesc": "Вільний час надходить безпосередньо з календаря Tutlio, тому клієнти запитують лише ті години, у які ви справді плануєте викладати.",
  "feature.digital-business-card.instantEnquiries": "Запити на заняття, поки ви викладаєте",
  "feature.digital-business-card.instantEnquiriesDesc": "Учень або хтось із батьків вибирає заняття, формат і час та залишає свої дані. Ви отримуєте повний запит без листування про розклад.",
  "feature.digital-business-card.professionalBrand": "Професійне перше враження",
  "feature.digital-business-card.professionalBrandDesc": "Покажіть фото, підхід до викладання, предмети, ціни, перевірені відгуки й фірмові кольори на сторінці, що зручно працює на будь-якому телефоні.",
  "feature.digital-business-card.faq.whatShowsQ": "Що можна показати на цифровій візитці?",
  "feature.digital-business-card.faq.whatShowsA": "Ви можете додати розповідь про себе, предмети, формати занять, публічні ціни, вільний час із календаря, місце проведення, мови, посилання на соцмережі й перевірені відгуки учнів.",
  "feature.digital-business-card.faq.howBookingWorksQ": "Чи одразу клієнт бронює підтверджене заняття?",
  "feature.digital-business-card.faq.howBookingWorksA": "Клієнт вибирає заняття й доступний час та надсилає повний запит на бронювання. Ви отримуєте його в Tutlio й можете підтвердити нового учня, перш ніж заняття з’явиться в розкладі.",
  "feature.digital-business-card.faq.whereShareQ": "Де ділитися сторінкою?",
  "feature.digital-business-card.faq.whereShareA": "Використовуйте її в Instagram, TikTok, групах Facebook, рекламі, підписах листів, повідомленнях і QR-кодах. Посилання залишається актуальним, навіть коли змінюються ціни чи календар.",
  "feature.digital-business-card.demo.eyebrow": "Інтерактивний перегляд для клієнта",
  "feature.digital-business-card.demo.title": "Спробуйте процес бронювання",
  "feature.digital-business-card.demo.desc": "Виберіть заняття й час нижче. Саме так просто новий клієнт проходить шлях за вашим посиланням.",
  "feature.digital-business-card.demo.profile": "Репетитор математики · 9–12 класи",
