  "pwa.guideIntro": "Додайте Tutlio на головний екран телефону й користуйтеся ним як звичайним застосунком — на весь екран і зі швидким доступом.",
  "pwa.iosStep1": "Відкрийте Tutlio в Safari й натисніть кнопку «Поділитися» (квадрат зі стрілкою) внизу екрана.",
  "pwa.iosStep2": "Прокрутіть униз і натисніть «На початковий екран».",
