  "enterprise.successTitle": "Дякуємо!",
  "enterprise.successDesc": "Ми отримали ваш запит і відповімо протягом 1–2 робочих днів.",
  "enterpriseSuccess.title": "Оплату отримано!",
  "enterpriseSuccess.orgDesc": "Купівлю ліцензій підтверджено. Їх додають до вашої організації.",
  "enterpriseSuccess.goToCompany": "Перейти до панелі організації",
