  "enterpriseSuccess.checkEmail": "Перевірте електронну пошту - ми надіслали посилання для встановлення пароля адміністратора й доступу до панелі організації. Лист може надійти за хвилину.",
  "enterpriseSuccess.backHome": "На головну сторінку",
  "landing.leadSuccess": "Дякуємо! Ми зв’яжемося з вами.",
  "orgTutorPolicy.title": "Внутрішні правила для репетиторів",
  "orgTutorPolicy.intro": "Перед користуванням платформою ознайомтеся з внутрішніми правилами організації.",
  "orgTutorPolicy.acceptBtn": "Зрозуміло",
  "orgTutorPolicy.viewBtn": "Переглянути внутрішні правила",
  "orgTutorPolicy.s1Title": "1. Загальні положення",
  "orgTutorPolicy.s1Body": "Ці правила регулюють користування платформою Tutlio («Платформа») викладачем або репетитором («Репетитор»). Вас запросила на Платформу освітня агенція, школа чи репетиторський центр, який ви представляєте («Організація»). Технічне обслуговування й підтримку Платформи здійснює MB Tutlio. Користуючись обліковим записом, ви погоджуєтеся із цими Правилами й Політикою конфіденційності.",
  "orgTutorPolicy.s2Title": "2. Керування обліковим записом і розкладом",
  "orgTutorPolicy.s2Intro": "Платформу створено, щоб вам не доводилося витрачати час на узгодження занять з учнями.",
  "orgTutorPolicy.s2Link": "Унікальне посилання: ви отримуєте особисте посилання для бронювання занять відповідно до предметів, які викладаєте. Учні використовують його для запису.",
  "orgTutorPolicy.s2Calendar": "Синхронізація календаря: ваш вільний час безпосередньо залежить від інтеграції з Google Calendar (2-стороння синхронізація). Ви особисто відповідаєте за точність і актуальність вільного часу в календарі. Платформа не дозволяє учням бронювати час, позначений як зайнятий.",
  "orgTutorPolicy.s2Security": "Безпека облікового запису: ваш обліковий запис є особистим. Ви зобов’язані зберігати облікові дані в безпеці й не передавати їх третім особам.",
  "orgTutorPolicy.s3Title": "3. Скасування занять і список очікування",
  "orgTutorPolicy.s3Intro": "Платформа допомагає максимально заповнювати розклад і уникати порожніх місць:",
  "orgTutorPolicy.s3Auto": "Якщо учень скасовує заняття, Платформа автоматично надсилає іншим учням із вашого списку очікування сповіщення (SMS / електронною поштою) із пропозицією вільного часу. Додаткові дії з вашого боку не потрібні.",
  "orgTutorPolicy.s3Rules": "Правила скасування занять — терміни й наслідки — установлює ваша Організація.",
  "orgTutorPolicy.s4Title": "4. Фінанси й оплати",
  "orgTutorPolicy.s4Intro": "Вам не потрібно турбуватися про рахунки чи отримання оплат від батьків:",
  "orgTutorPolicy.s4Advance": "Усі оплати учнів або батьків за ваші заняття збираються заздалегідь через Платформу й переказуються безпосередньо вашій Організації.",
  "orgTutorPolicy.s4Confirmed": "Ви проводите заняття лише після його підтвердження в системі, що означає, що оплату вже списано.",
  "orgTutorPolicy.s4Contact": "Щодо винагороди, графіка виплат та інших фінансових питань звертайтеся безпосередньо до адміністратора Організації. MB Tutlio не проводить прямих фінансових операцій із Репетиторами.",
  "orgTutorPolicy.s5Title": "5. Захист даних учнів (GDPR)",
  "orgTutorPolicy.s5Intro": "Як Репетитор ви маєте доступ до персональних даних учнів, внутрішніх нотаток і навчальних матеріалів. Ви зобов’язуєтеся:",
  "orgTutorPolicy.s5Use": "Використовувати ці дані виключно для організації та проведення занять.",
  "orgTutorPolicy.s5NoCopy": "Не копіювати, не експортувати й не поширювати контактні дані учнів або батьків поза Платформою.",
  "orgTutorPolicy.s5Notes": "Захищати внутрішні записи Організації про прогрес учнів, які доступні лише вам і адміністрації Організації, а не учням чи батькам.",
  "orgTutorPolicy.s5Termination": "Після припинення робочих відносин з Організацією ваш доступ до цих даних буде негайно скасовано.",
  "orgTutorPolicy.s6Title": "6. Технічна робота й обмеження відповідальності",
  "orgTutorPolicy.s6Body": "Заборонено використовувати Платформу з незаконною метою, поширювати шкідливі посилання в навчальних матеріалах або іншим чином порушувати роботу системи. MB Tutlio забезпечує роботу й технічне обслуговування Платформи, але не відповідає за збої через ваше інтернет-з’єднання, несправність пристроїв або неправильно налаштований Google Calendar.",
  "orgTutorPolicy.s7Title": "7. Підтримка й контакти",
  "orgTutorPolicy.s7Org": "Щодо розкладу занять, винагороди, призначення учнів чи організації роботи звертайтеся до адміністратора вашої Організації.",
  "orgTutorPolicy.s7Tech": "У разі технічних помилок Платформи, зокрема проблем із синхронізацією календаря чи сповіщеннями, повідомте адміністратора Організації, який зв’яжеться з технічною підтримкою Tutlio.",
  "register.orgPolicyConsent": "Користуючись нашою платформою, ви погоджуєтеся з",
  "register.orgPolicyLink": "внутрішніми правилами",
