  "quiz.intro.company.visualAlt": "Адміністратор репетиторської компанії координує репетиторів у єдиному робочому процесі",
  "quiz.intro.company.insight": "Ми врахуємо розмір команди, робоче навантаження й головну перешкоду, щоб підібрати відповідний спільний простір.",
  "quiz.intro.school.eyebrow": "Для сучасних освітніх організацій",
