  "quiz.offer.testimonial.solo.name3": "Ieva",
  "quiz.offer.testimonial.solo.role3": "Репетитор хімії та біології",
  "quiz.offer.testimonial.solo.copy3": "«Публічна сторінка й бронювання за одним посиланням допомагають новим учням швидше вирішити, а мені більше не потрібно надсилати всім ту саму інформацію окремо».",
  "quiz.offer.testimonial.solo.name4": "Lukas",
  "quiz.offer.testimonial.solo.role4": "Репетитор фізики",
  "quiz.offer.testimonial.solo.copy4": "«Я одразу бачу заняття, зміни й статуси оплат у календарі. Щоденні адміністративні справи стали значно коротшими й зрозумілішими».",
  "quiz.offer.testimonial.company.copy1": "«Раніше зміни занять, коментарі репетиторів і години надходили окремими повідомленнями. Тепер адміністрація бачить повну картину в одному розкладі».",
  "quiz.offer.testimonial.company.name2": "Незалежний репетиторський центр",
  "quiz.offer.testimonial.company.role2": "Власник · 8 репетиторів",
  "quiz.offer.testimonial.company.copy2": "«Раніше я проводив п’ятничні вечори, звіряючи календар із повідомленнями репетиторів перед розрахунком винагороди. Із Tutlio більшість цих перевірок уже виконано».",
  "quiz.offer.testimonial.company.name3": "Студія мовного навчання",
  "quiz.offer.testimonial.company.role3": "Керівник операційної роботи · 14 репетиторів",
  "quiz.offer.testimonial.company.copy3": "«Коли заняття переноситься, команда одразу бачить однакове оновлення. Додаткових повідомлень менше, а батьки отримують значно зрозуміліші відповіді».",
  "quiz.offer.testimonial.company.name4": "Академія підготовки до іспитів",
  "quiz.offer.testimonial.company.role4": "Фінансовий координатор · 22 репетитори",
  "quiz.offer.testimonial.company.copy4": "«Наші правила винагороди залежать від типу заняття, тому кінець місяця вимагав багато ручних перевірок. Процес Tutlio зробив цю роботу значно спокійнішою».",
  "quiz.offer.testimonial.school.name2": "Незалежна громадська школа",
  "quiz.offer.testimonial.school.role2": "Координатор зарахування · 86 учнів",
  "quiz.offer.testimonial.school.copy2": "«Під час зарахування доводилося відстежувати форми, дані батьків і підписані договори в різних папках. Тепер команда супроводжує кожну родину з одного місця».",
  "quiz.offer.testimonial.school.name3": "Центр позашкільного навчання",
  "quiz.offer.testimonial.school.role3": "Адміністратор · 120 учнів",
  "quiz.offer.testimonial.school.copy3": "«Графіки внесків значно спростили контроль оплат. Я бачу, що потрібно сплатити, ще до звернення до батьків, а не складаю список вручну».",
  "quiz.offer.testimonial.school.name4": "Школа мистецької освіти",
  "quiz.offer.testimonial.school.role4": "Фінансовий координатор · 9 програм",
  "quiz.offer.testimonial.school.copy4": "«Експорт для бухгалтерії тепер формується з тих самих записів, що й договори та оплати, тому наприкінці місяця виправлень значно менше».",
  "quiz.offer.savings.eyebrow": "Оцінка впливу на витрати часу",
  "quiz.offer.savings.subtitle": "Орієнтовне скорочення повторюваних адміністративних справ після об’єднання цих процесів у Tutlio.",
