  "schoolsLanding.faq.whatIsQ": "Що таке Tutlio для шкіл?",
  "schoolsLanding.faq.whatIsA": "Tutlio Schools - це програма для управління школами репетиторів: розклад учителів, CRM для учнів, договори, платежі та звітність на одній платформі.",
  "schoolsLanding.faq.whoForQ": "Для кого призначено Tutlio Schools?",
