  "landing.custom.badge": "Головна відмінність",
  "landing.custom.title": "Програма, що підлаштовується під те, як ви працюєте - а не навпаки",
  "landing.custom.sub": "Кожна школа й агенція працює трохи інакше. Коли стандартний процес не підходить, ми адаптуємо Tutlio під ваш - зазвичай за тижні, а не квартали. Ось кілька речей, які ми вже зробили для клієнтів:",
  "landing.custom.ex1Title": "Річні договори з електронним підписом",
  "landing.custom.ex1Desc": "Приватній школі було потрібно, щоб батьки підписували річні договори електронно, платили частинами, а кожен платіж потрапляв до експорту, готового для бухгалтерії. Тепер увесь цикл відбувається всередині Tutlio.",
  "landing.custom.ex2Title": "Правила оплати та комісії репетиторів",
  "landing.custom.ex2Desc": "Агенція платить кожному репетиторові залежно від предмета й типу заняття, додаючи комісію компанії. Ми змоделювали їхні правила, тож місячні звіти репетиторів і рахунки формуються автоматично.",
  "landing.custom.ex3Title": "Пропозиції для батьків в один клік",
  "landing.custom.ex3Desc": "Школа хотіла пропонувати додаткові заняття електронною поштою та дозволити батькам приймати їх одним натисканням - без облікового запису й друку. Тепер прийняття, виставлення рахунків і запрошення на перше заняття відбуваються самі.",
  "landing.custom.ex4Title": "Ваш бренд на вашому сайті",
  "landing.custom.ex4Desc": "Організація хотіла власний логотип і кольори, а також вхід, вбудований у її сайт, щоб учні та батьки ніколи не відчували, що залишили його. Тепер Tutlio працює під їхнім брендом.",
  "landing.custom.note": "Нічого з цього не є окремою спеціальною версією. Кожна адаптація стає частиною того самого продукту, яким уже користується ваша команда, з усіма майбутніми оновленнями.",
  "landing.custom.cta": "Розкажіть, як ви працюєте",
  "landing.custom.soloTitle": "Чогось бракує?",
  "landing.custom.soloNote": "Ми регулярно створюємо функції для окремих клієнтів - від одного правила оплати до цілого робочого процесу. Напишіть, що заощадило б вам час.",
