  "compare.customBody": "Більшість платформ для репетиторства можна налаштувати, але не змінити. Tutlio створює й підтримує невелика команда, яка переносить робочі процеси окремих клієнтів - договірні шляхи, правила оплати праці, посилання для підтвердження батьками, портали з вашим брендом - у той самий продукт, яким користуються всі. Якщо у вашого центру чи агенції є процес, якого має дотримуватися програма, ми його створимо.",
